    // Initialize the controller and a mock scope
    beforeEach(inject(function ($controller, $rootScope, $injector, $routeParams, $templateCache, $location, $q) {
        scope = $rootScope.$new();
        var huashan = $injector.get('HUASHAN');
        console.log(huashan);
        var Session = $injector.get("Session");
        Session.create("fakeCredentials");
        var $cookies = $injector.get("$cookies");
        $cookies.huashansession = "fakeCredentials";
        controller = $controller;
        httpBackend.expect('GET', 'https://localhost/kirk/wizard/main?command=GetPortfolioStructure&kreds=fakeCredentials&templateName=accountDev&isPlatform=false');
        httpBackend.expect('GET', 'https://localhost/kirk/wizard/main?command=GetPotentialTables&kreds=fakeCredentials&templateName=accountDev');
        httpBackend.expect('GET', 'https://localhost/kirk/wizard/main?command=GetAppStructure&kreds=fakeCredentials&templateName=accountDev&isPlatform=false');
        httpBackend.expect('GET', 'https://localhost/kirk/wizard/main?command=GetDataStructure&kreds=fakeCredentials&templateName=accountDev&isPlatform=false');
        $routeParams.templateID = "accountDev";
        $location.path('/portfoliostructure/accountDev');
        $rootScope.$digest();
        portfolioStructureController = controller('PortfolioStructureController', { $scope: scope, $routeParams: { templateID: "accountDev" } });
        flush();
        expect(portfolioStructureController).not.toBe(undefined);
    }));
    it("should initialize saveComplete correctly", function () {
        // console.log("-->>",portfolioStructureController.saveComplete);
        expect(portfolioStructureController.saveComplete).toBe(true);
    });
    describe("add portfolio structure item", function () {
        it("should add a new app structure item properly", function () {
            portfolioStructureController.addNewPortfolioStructure("Compare Value 1", "COMPARE_VALUE");
            var compareValue = {
                "Command": "COMPARE_VALUE",
                "Display": "Compare Value 1",
                "ID": "CompareValue1",
                "UsePostProcessingOutputs": false,
                "Visible": true,
                "Parameters": {
                    "InputKeys": []
                }
            };
            expect(portfolioStructureController.portfolioStructure.MENU[6].ID).toEqual(compareValue.ID);
        });
        it("should not generate duplicate IDs", function () {
            var lastMenuIndex = portfolioStructureController.portfolioStructure.MENU.length;
            portfolioStructureController.addNewPortfolioStructure("Compare Value 1", "COMPARE_VALUE");
            expect(portfolioStructureController.portfolioStructure.MENU[lastMenuIndex].ID).toEqual("CompareValue1");
            portfolioStructureController.addNewPortfolioStructure("Compare Value 1", "COMPARE_VALUE");
            expect(portfolioStructureController.portfolioStructure.MENU[lastMenuIndex + 1].ID).toEqual("CompareValue10");
        });
    });
    describe("Compare Value should have Total parameter, ", function () {
        it("should have default value false when create a new Compare Value", function () {
            var lastMenuIndex = portfolioStructureController.portfolioStructure.MENU.length;
            portfolioStructureController.addNewPortfolioStructure("Compare Value 2", "COMPARE_VALUE");
            expect(portfolioStructureController.portfolioStructure.MENU[lastMenuIndex].Parameters.Total).toEqual(false);
        });
    });
    describe("Bucket Manager", function () {
        var bucketManager;
        var origBuckets;
        beforeEach(function () {
            origBuckets = [
                {
                    "LT": 0.1,
                    "Name": "<10%"
                },
                {
                    "GE": 0.1,
                    "Name": "10-30%",
                    "LT": 0.3
                },
                {
                    "GE": 0.3,
                    "Name": "30-50%",
                    "LT": 0.5
                },
                {
                    "GE": 0.5,
                    "Name": "50-70%",
                    "LT": 0.7
                },
                {
                    "GE": 0.7,
                    "Name": "70-90%",
                    "LT": 0.9
                },
                {
                    "GE": 0.9,
                    "Name": ">=90%"
                }
            ];
            bucketManager = new BucketManager(origBuckets);
        });
        it("Should produce 6 buckets", function () {
            expect(bucketManager.editableBuckets.length).toEqual(6);
        });
        it("Should copy names", function () {
            var index = 0;
            bucketManager.editableBuckets.forEach(function (bucket) {
                expect(bucket.Name).toEqual(origBuckets[index].Name);
                index++;
            });
        });
        it("Should have options for drop down rules", function () {
            expect(bucketManager.rule1Options).toEqual([{ Label: "", Value: "NONE" }, { Label: ">", Value: "GT" }, { Label: ">=", Value: "GE" }]);
            expect(bucketManager.rule2Options).toEqual([{ Label: "", Value: "NONE" }, { Label: "<", Value: "LT" }, { Label: "<=", Value: "LE" }]);
        });
        it("Should set produce correct rule types and values for bucket 0", function () {
            var bucket = bucketManager.editableBuckets[0];
            expect(bucket.rule1Type).toEqual({ Label: "", Value: "NONE" });
            expect(bucket.rule1Value).toEqual(undefined);
            expect(bucket.rule2Type).toEqual({ Label: "<", Value: "LT" });
            expect(bucket.rule2Value).toEqual(0.1);
        });
        it("Should set produce correct rule types and values for bucket 1", function () {
            var bucket = bucketManager.editableBuckets[1];
            expect(bucket.rule1Type).toEqual({ Label: ">=", Value: "GE" });
            expect(bucket.rule1Value).toEqual(0.1);
            expect(bucket.rule2Type).toEqual({ Label: "<", Value: "LT" });
            expect(bucket.rule2Value).toEqual(0.3);
        });
        it("Should set produce correct rule types and values for bucket 5", function () {
            var bucket = bucketManager.editableBuckets[5];
            expect(bucket.rule1Type).toEqual({ Label: ">=", Value: "GE" });
            expect(bucket.rule1Value).toEqual(0.9);
            expect(bucket.rule2Type).toEqual({ Label: "", Value: "NONE" });
            expect(bucket.rule2Value).toEqual(undefined);
        });
        it("Should set editables to false", function () {
            bucketManager.editableBuckets.forEach(function (editableBucket) {
                expect(editableBucket.nameEditable).toEqual(false);
                expect(editableBucket.rulesEditable).toEqual(false);
            });
        });
        it("Should extract normal buckets", function () {
            expect(bucketManager.buckets()).toEqual(origBuckets);
        });
    });
